#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long h;
    long long w;
    cin >> h >> w;

    const long long MOD = 1000000007;
    int rowsCount = (int)h, size = 1 << rowsCount;
    vector<long long> dp(size, 0), next(size);
    dp[0] = 1;
    for (int c = 0; c < w; c++) {
        for (int r = 0; r < rowsCount; r++) {
            fill(next.begin(), next.end(), 0);
            int bit = 1 << r;
            for (int mask = 0; mask < size; mask++) {
                long long v = dp[mask];
                if (v == 0) continue;
                if (mask & bit) {
                    next[mask ^ bit] = (next[mask ^ bit] + v) % MOD;
                } else {
                    if (c + 1 < w) next[mask | bit] = (next[mask | bit] + v) % MOD;
                    if (r + 1 < rowsCount && !(mask & (bit << 1))) next[mask | (bit << 1)] = (next[mask | (bit << 1)] + v) % MOD;
                }
            }
            dp = next;
        }
    }
    cout << dp[0] << "\n";

    return 0;
}

