import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long h = Long.parseLong(next());
        long w = Long.parseLong(next());

        final long MOD = 1000000007L;
        int rowsCount = (int) h, size = 1 << rowsCount;
        long[] dp = new long[size];
        long[] next = new long[size];
        dp[0] = 1;
        for (int c = 0; c < w; c++) {
            for (int r = 0; r < rowsCount; r++) {
                Arrays.fill(next, 0);
                int bit = 1 << r;
                for (int mask = 0; mask < size; mask++) {
                    long v = dp[mask];
                    if (v == 0) continue;
                    if ((mask & bit) != 0) {
                        next[mask ^ bit] = (next[mask ^ bit] + v) % MOD;
                    } else {
                        if (c + 1 < w) next[mask | bit] = (next[mask | bit] + v) % MOD;
                        if (r + 1 < rowsCount && (mask & (bit << 1)) == 0) next[mask | (bit << 1)] = (next[mask | (bit << 1)] + v) % MOD;
                    }
                }
                long[] swap = dp;
                dp = next;
                next = swap;
            }
        }
        System.out.println(dp[0]);
    }
}
